/*
 * GSM 4G LTE HTTP Client — Arduino Uno + Quectel EC25/BG96
 * Makes an HTTP GET request every 10 seconds and prints the response.
 * Demonstrates LTE CAT-4 AT commands for TCP/IP and HTTP.
 */

#include <GSM.h>

GSM gsm;

String serverUrl = "http://example.com/api/data";
int requestCount = 0;

void setup() {
  Serial.begin(115200);
  while (!Serial);

  Serial.println("GSM 4G LTE HTTP Client Starting...");

  // Initialize GSM module
  gsm.begin();

  // Check network registration and signal
  Serial.println("AT+COPS?");
  Serial.println("AT+CREG?");
  Serial.println("AT+CSQ");

  Serial.println("GSM 4G LTE Client ready!");
  Serial.println("IMEI: " + gsm.getIMEI());
  Serial.println("---");
}

void loop() {
  requestCount++;

  Serial.print("HTTP GET request #");
  Serial.println(requestCount);

  gsm.httpGet(serverUrl);

  delay(1000);
  String response = gsm.httpRead();
  if (response.length() > 0) {
    Serial.print("HTTP Response: ");
    Serial.println(response);
  }

  Serial.println("---");

  delay(10000);
}
